{"cards": [{"node_code": "N_2fc0926cc866c8d7", "definition": "研究作用于自主神经系统（交感、副交感神经及神经肌肉接头）药物的作用机制、效应及临床应用，涵盖拟胆碱、抗胆碱、拟肾上腺素及抗肾上腺素药等。", "boundary": "本节点聚焦于外周自主神经系统的药理机制，重点在于药物对胆碱能或肾上腺素能受体的调节作用及其对平滑肌、腺体、心脏等效应器的影响。不涵盖中枢神经系统内的神经递质调节（归中枢神经系统药理），也不涉及药物在体内的代谢动力学过程（归药动学）。", "includes": ["拟胆碱药与抗胆碱药的作用机制及临床应用", "拟肾上腺素药与抗肾上腺素药（如β受体阻滞剂）的药理特性", "神经肌肉接头阻断药及胆碱酯酶抑制药的作用研究"], "excludes": ["作用于中枢神经系统的镇静催眠、抗精神病等药物（归中枢神经系统药理）", "药物在体内的吸收、分布、代谢及排泄规律（归药动学）"], "sibling_distinctions": [{"other_code": "N_38ccac42b4b1d269", "rule": "本节点关注外周自主神经（交感/副交感）及神经肌肉接头的药物作用，兄弟节点关注中枢神经系统（脑、脊髓）内的神经递质及药物效应。"}, {"other_code": "N_bae6737c849962c1", "rule": "本节点侧重通过神经递质受体调节心脏及血管功能，兄弟节点侧重直接作用于心肌细胞、血管平滑肌或影响血液成分的药物。"}], "cross_boundary_rule": "若药物同时具有外周自主神经作用和中枢效应，主挂载依据其主要治疗靶点；若主要调节外周平滑肌/心脏，归本节点；若主要调节中枢行为/意识，归中枢神经系统药理。"}, {"node_code": "N_38ccac42b4b1d269", "definition": "研究作用于中枢神经系统（脑、脊髓）药物的作用机制、效应及临床应用，涵盖镇静催眠、抗焦虑、抗精神病、抗抑郁、抗癫痫及镇痛药等。", "boundary": "本节点聚焦于药物对中枢神经递质系统（如GABA、谷氨酸、多巴胺、5-HT等）的调节及其对意识、情绪、认知、运动等高级神经功能的影响。不涵盖外周自主神经系统的药物作用（归传出神经系统药理），也不涉及药物透过血脑屏障的动力学过程（归药动学）。", "includes": ["镇静催眠药、抗焦虑药及抗精神病药的药理机制", "抗抑郁药、抗双相情感障碍药及抗癫痫药的作用研究", "中枢镇痛药（如阿片类）及抗帕金森病药物的效应分析"], "excludes": ["主要作用于外周神经肌肉接头或自主神经末梢的药物（归传出神经系统药理）", "药物在脑组织中的分布浓度及代谢动力学参数（归药动学）"], "sibling_distinctions": [{"other_code": "N_2fc0926cc866c8d7", "rule": "本节点关注中枢神经递质及高级神经功能（意识、情绪、认知）的药物调节，兄弟节点关注外周自主神经及神经肌肉接头的药物作用。"}, {"other_code": "N_bae6737c849962c1", "rule": "本节点侧重调节中枢神经功能，兄弟节点侧重调节心血管系统（心脏、血管）及血液系统的生理功能。"}], "cross_boundary_rule": "若药物具有显著的中枢和外周双重作用，主挂载依据其临床主要适应症；若用于调节精神/神经行为，归本节点；若用于调节血压/心率，归心血管系统药理。"}, {"node_code": "N_bae6737c849962c1", "definition": "研究作用于心血管系统（心脏、血管、血液）药物的作用机制、效应及临床应用，涵盖抗高血压、抗心律失常、抗心绞痛、抗心力衰竭及调血脂药等。", "boundary": "本节点聚焦于药物对心肌收缩力、心率、血管张力、血压及血液流变学的影响。包括直接作用于心肌细胞、血管平滑肌或影响凝血/纤溶系统的药物。不涵盖通过神经递质间接调节心血管功能的药物（归传出神经系统药理），也不涉及药物在体内的代谢过程（归药动学）。", "includes": ["抗高血压药、抗心律失常药及抗心绞痛药的药理机制", "抗心力衰竭药、强心苷及利尿药（心血管应用）的作用研究", "调血脂药、抗动脉粥样硬化药及抗凝血/抗血小板药的效应分析"], "excludes": ["主要作用于外周自主神经受体以调节血压/心率的药物（归传出神经系统药理）", "药物在心血管组织中的分布及代谢动力学参数（归药动学）"], "sibling_distinctions": [{"other_code": "N_2fc0926cc866c8d7", "rule": "本节点侧重直接作用于心肌/血管/血液成分的药物，兄弟节点侧重通过神经递质受体间接调节心血管功能的药物。"}, {"other_code": "N_38ccac42b4b1d269", "rule": "本节点关注心血管生理功能的药物调节，兄弟节点关注中枢神经功能（意识、情绪、认知）的药物调节。"}], "cross_boundary_rule": "若药物既影响心血管又影响其他系统，主挂载依据其主要治疗靶点；若主要调节血压/心率/血流，归本节点；若主要调节神经递质，归传出或中枢神经系统药理。"}]}
